using System;
using System.Collections.Generic;
using UnityEngine;

namespace Hollow.HoUnityTools.HoCamera
{
    [Serializable]
    public struct HoCameraFrame
    {
        public float frame;
        public Vector3 position;
        public Quaternion rotation;
        public bool orthographic;
        public float fieldOfView;
        public float orthographicSize;
        public float nearClipPlane;
        public float farClipPlane;
        public Vector2 lensShift;
    }

    /// <summary>Imported, renderer-neutral camera samples. The child AnimationClip is generated by the editor importer.</summary>
    public sealed class HoCameraAsset : ScriptableObject
    {
        [SerializeField] private string sourceCamera;
        [SerializeField, Min(0.0001f)] private float frameRate = 24f;
        [SerializeField] private int startFrame;
        [SerializeField] private int endFrame;
        [SerializeField] private bool orthographic;
        [SerializeField] private float fieldOfView = 60f;
        [SerializeField] private float orthographicSize = 5f;
        [SerializeField] private float nearClipPlane = 0.01f;
        [SerializeField] private float farClipPlane = 1000f;
        [SerializeField] private Vector2 lensShift;
        [SerializeField] private AnimationClip animationClip;
        [SerializeField] private List<HoCameraFrame> frames = new List<HoCameraFrame>();

        public string SourceCamera => sourceCamera;
        public float FrameRate => frameRate;
        public int StartFrame => startFrame;
        public int EndFrame => endFrame;
        public bool Orthographic => orthographic;
        public float FieldOfView => fieldOfView;
        public float OrthographicSize => orthographicSize;
        public float NearClipPlane => nearClipPlane;
        public float FarClipPlane => farClipPlane;
        public Vector2 LensShift => lensShift;
        public AnimationClip AnimationClip => animationClip;
        public IReadOnlyList<HoCameraFrame> Frames => frames;
        public float Duration => Mathf.Max(0f, (endFrame - startFrame) / Mathf.Max(0.0001f, frameRate));

        public void SetData(string name, float fps, int first, int last, HoCameraFrame initial,
            List<HoCameraFrame> samples, AnimationClip clip)
        {
            sourceCamera = name ?? string.Empty;
            frameRate = Mathf.Max(0.0001f, fps);
            startFrame = first;
            endFrame = Mathf.Max(first, last);
            orthographic = initial.orthographic;
            fieldOfView = initial.fieldOfView;
            orthographicSize = initial.orthographicSize;
            nearClipPlane = initial.nearClipPlane;
            farClipPlane = initial.farClipPlane;
            lensShift = initial.lensShift;
            frames = samples ?? new List<HoCameraFrame>();
            animationClip = clip;
        }

        public HoCameraFrame Evaluate(float frame)
        {
            if (frames == null || frames.Count == 0)
                return new HoCameraFrame { frame = frame, orthographic = orthographic, fieldOfView = fieldOfView,
                    orthographicSize = orthographicSize, nearClipPlane = nearClipPlane, farClipPlane = farClipPlane,
                    lensShift = lensShift, rotation = Quaternion.identity };
            if (frame <= frames[0].frame) return frames[0];
            int next = 1;
            while (next < frames.Count && frames[next].frame < frame) next++;
            if (next >= frames.Count) return frames[frames.Count - 1];
            HoCameraFrame a = frames[next - 1];
            HoCameraFrame b = frames[next];
            float t = Mathf.InverseLerp(a.frame, b.frame, frame);
            a.frame = frame;
            a.position = Vector3.LerpUnclamped(a.position, b.position, t);
            a.rotation = Quaternion.SlerpUnclamped(a.rotation, b.rotation, t);
            a.fieldOfView = Mathf.LerpUnclamped(a.fieldOfView, b.fieldOfView, t);
            a.orthographicSize = Mathf.LerpUnclamped(a.orthographicSize, b.orthographicSize, t);
            a.nearClipPlane = Mathf.LerpUnclamped(a.nearClipPlane, b.nearClipPlane, t);
            a.farClipPlane = Mathf.LerpUnclamped(a.farClipPlane, b.farClipPlane, t);
            a.lensShift = Vector2.LerpUnclamped(a.lensShift, b.lensShift, t);
            // Projection mode is discrete; the sample at the left side owns the interval.
            return a;
        }

        public void ApplySnapshot(Camera camera)
        {
            if (camera == null) return;
            Apply(camera, frames != null && frames.Count > 0 ? frames[0] : new HoCameraFrame
            {
                orthographic = orthographic, fieldOfView = fieldOfView, orthographicSize = orthographicSize,
                nearClipPlane = nearClipPlane, farClipPlane = farClipPlane, lensShift = lensShift,
                rotation = camera.transform.rotation, position = camera.transform.position
            });
        }

        public void ApplyAtFrame(Camera camera, float frame)
        {
            if (camera != null) Apply(camera, Evaluate(frame));
        }

        private static void Apply(Camera camera, HoCameraFrame value)
        {
            camera.transform.position = value.position;
            camera.transform.rotation = value.rotation;
            camera.orthographic = value.orthographic;
            camera.fieldOfView = Mathf.Clamp(value.fieldOfView, 0.01f, 179.9f);
            camera.orthographicSize = Mathf.Max(0.0001f, value.orthographicSize);
            camera.nearClipPlane = Mathf.Max(0.00001f, value.nearClipPlane);
            camera.farClipPlane = Mathf.Max(camera.nearClipPlane + 0.00001f, value.farClipPlane);
            // Lens shift is a physical-camera feature. Preserve a normal camera when the
            // source has no shift; this keeps FOV-only imports renderer-neutral.
            if (value.lensShift.sqrMagnitude > 1e-12f)
            {
                camera.usePhysicalProperties = true;
                camera.lensShift = value.lensShift;
            }
        }
    }
}
